		return b, nil
	case "up":
		b.focusedField = max(b.focusedField-1, brFieldRepo)
		b.updateFocus()
		return b, nil
	case " ":
		if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
			row := b.rows[b.focusedField-1]
			if row.groupSlug != "" {
				b.toggleGroup(row.groupSlug)
				return b, nil
			}
			key := b.entries[row.entry].key
			b.selectedRegs[key] = !b.selectedRegs[key]
			return b, nil
		}
	case "enter":
		if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
			return b.submitSearch()
		}
		b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
		b.updateFocus()
		return b, nil
	}
	return b.delegateUpdate(msg)
}

// credsFor returns the credentials to search entry with, and nothing at all
// when the registry — or the group it belongs to — is marked anonymous (D12).
// Docker keys credentials by host, so a Nexus instance with one repository
// logged into would otherwise send that login to every repository it serves.
func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
	if !config.UsesCredentials(entry.authMode) {
		return "", ""
	}
	// Credentials come from the parent registry, or the entry itself for a
	// registry that is not a group member.
	credURL := entry.URL
	if entry.parentURL != "" {
		credURL = entry.parentURL
	}
	var username string
	for _, reg := range b.registries {
		if reg.URL == credURL {
			username = reg.Username
			break
		}
	}
	storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
	if username == "" {
		username = storedUser
	}
	return username, storedPass
}

func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
	repo := strings.TrimSpace(b.repoInput.Value())
	if repo == "" {
		return b, nil
	}

	b.tags = nil
	b.registryFilter = resultFilter{}
	b.pendingSearches = 0
	b.filterInput.SetValue("")
	b.filterActive = false
	// A new search starts from the default order, not wherever the last one's
	// `.` presses left the table.
	b.tagTable.SetSort(tagColumnTag, false)

	var cmds []tea.Cmd
	for _, entry := range b.entries {
		if !b.selected(entry) {
			continue
		}
		username, storedPass := b.credsFor(entry)
		alias := entry.Alias
		if entry.ParentAlias != "" {
			alias = entry.ParentAlias + "/" + entry.Alias
		}
		normalizedRepo := normalizeRepoForRegistry(entry.URL, repo)
		apiURL := registryAPIURL(entry.URL)
		b.pendingSearches++
		cmds = append(cmds, searchRegistryTagsCmd(entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
	}

	if len(cmds) == 0 {
		return b, nil
	}

	b.state = browserStateTags
	b.tagTable.Focus()
	b.rebuildTagTable()
	cmds = append(cmds, b.spinner.Tick)
	return b, tea.Batch(cmds...)
}

func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTagTable()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()
		b.resizeTagTable()
		return b, nil
	case "r":
		b.cycleRegistryFilter()
		return b, nil
	case "enter":
		return b.openTagScanDetails()
	case "p":
		return b.pullSelectedTag()
	case "ctrl+s":
		return b.requestDirectScan()
	}
	// Navigation and `.` are the table's. `/` never reaches it: the browser's
	// own filter took the key two cases above, and the table declares no
	// searchable column, so it would decline it anyway.
	return b, b.tagTable.Update(msg)
}

// Anything else is left alone, so the view keeps its own actions.
func (m *Model[T]) Update(msg tea.Msg) tea.Cmd {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuild()
		return cmd
	}

	key, ok := msg.(tea.KeyMsg)
	if !ok {
		return nil
	}
	switch key.String() {
	case "/":
		// A table with nothing to search does not claim the key: activating a
		// search that can only ever match nothing would empty the list, and the
		// bar the user needs to see why is not in that view's footer.
		if !m.Searchable() {
			return nil
		}
		return m.bar.ActivateSearch()
	case ".":
		m.CycleSort()
	case "up", "k":
		m.table.MoveUp(1)
		m.afterCursorMove()
	case "down", "j":
		m.table.MoveDown(1)
		m.afterCursorMove()
	case "pgup":
		m.table.MoveUp(m.table.Height())
		m.afterCursorMove()
	case "pgdown":
		m.table.MoveDown(m.table.Height())
		m.afterCursorMove()
	case "g", "home":
		m.table.GotoTop()
		m.afterCursorMove()
	case "G", "end":
		m.table.GotoBottom()
		m.afterCursorMove()
	}
	return nil
}

package app

import (
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// helpViewportMinHeight keeps the overlay usable on a short window; below it
// the border and the scroll hint would leave no room for content.
const helpViewportMinHeight = 10

// helpOverlayMargin is the room the overlay box's border and padding take from
// the window, horizontally and vertically.
const helpOverlayMargin = 6

// maybeOpenHelp opens the help overlay for the active view, unless a field is
// focused — there "?" is a character to type.
func (a *App) maybeOpenHelp(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, ok := a.views[a.currentView]; !ok {
		return a, nil
	}
	if a.inEditMode() {
		return a, a.forwardToActiveView(msg)
	}

	provider, implements := a.views[a.currentView].(help.Provider)
	if !implements {
		return a, nil
	}

	height := max(a.height-helpOverlayMargin, helpViewportMinHeight)
	a.helpViewport = viewport.New(a.width-helpOverlayMargin, height)
	a.helpViewport.SetContent(help.Render(provider.GetHelpContent(), a.width))
	a.showHelp = true
	return a, nil
}

// handleHelpKeyMsg gère les touches clavier dans l'overlay d'aide
func (a *App) handleHelpKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc", "q", "?":
		a.showHelp = false
		return a, nil
	default:
		// Déléguer au viewport pour le scroll (↑↓/jk/PgUp/PgDn/g/G)
		var cmd tea.Cmd
		a.helpViewport, cmd = a.helpViewport.Update(msg)
		return a, cmd
	}
}

// renderHelpOverlay affiche un overlay avec l'aide de la vue courante
func (a *App) renderHelpOverlay() string {
	return theme.OverlayBoxStyle().Render(a.helpViewport.View() + "\n")
}

