	}

	// Mode normal - déléguer selon le type de commande
	switch msg.String() {
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "q", "ctrl+c":
		return m, tea.Quit
	case "ctrl+r":
		return m.handleManualRefresh()
	case "up", "down", "k", "j", "tab", "shift+tab", "g", "G", "home", "end":
		return m.handleTableNavigation(msg)
	case "ctrl+n", "e", "ctrl+d":
		return m.handleMonitorOperations(msg)
	case ".":
		return m.cycleSort()
	}

	return m, nil
}

// handleManualRefresh runs a check now, whatever the auto-refresh setting says.
//
// It is the only refresh control left here: the interval and auto-refresh are
// settings, and the configuration view owns them. Forcing a check is an action,
// not a setting, so it stays (Rule 111).
func (m Model) handleManualRefresh() (tea.Model, tea.Cmd) {
	if m.checking {
		return m, nil
	}

	m.checking = true
	return m, tea.Batch(
		m.spinner.Tick,
		checkComponents(m.config),
	)
}

// switchTab switches focus to the given tab
func (m *Model) switchTab(tab int) {
	m.activeTab = tab
	m.applyTabFocus()
}

// handleTableNavigation handles up, down, and tab navigation
func (m Model) handleTableNavigation(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "up", "k", "down", "j", "pgup", "pgdown", "g", "home", "G", "end":
		return m, m.getCurrentTable().Update(msg)
	case "tab":
		m.switchTab((m.activeTab + 1) % 2)
	case "shift+tab":
		m.switchTab((m.activeTab + 1) % 2)
	}

	return m, nil
}

	case ModeConfirmingDelete:
		if m.deleteConfirmModal != nil {
			var cmd tea.Cmd
			m.deleteConfirmModal, cmd = m.deleteConfirmModal.Update(msg)
			return m, cmd
		}
	}

	// Normal mode. Actions resolve the cursor through the table, which resolves
	// it against the very slice its rows were built from.
	switch msg.String() {
	case "left", "h":
		return m.handleDrillUp()
	case "right", "l":
		return m.handleDrillDown()
	case "esc":
		return m.handleDrillUp()
	case "ctrl+r":
		return m.handleRefresh()
	case "c":
		return m.handleCloneStart()
	case "ctrl+n":
		return m.handleCreateResource()
	case "ctrl+d":
		return m.handleDeleteStart()
	case "ctrl+w":
		return m.handleOpenInBrowser()
	}

	// Navigation, `/` and `.` are the table's, not the view's.
	return m, m.table.Update(msg)
}

// handleSelectingKey is the clone selection mode (Rule 135 unchanged): `space`
// ticks, `←→` still drill, `enter` confirms.
//
// `esc` leaves the mode rather than drilling up, because cancelling is what the
// key means when there is something to cancel; `←` is still the way up.
func (m Model) handleSelectingKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case " ":
		return m.handleSelectionToggle()
	case "enter":
		return m.handleSelectionConfirm()
	case "esc":
		return m.handleSelectionCancel()
	case "left", "h":
		return m.handleDrillUp()
	case "right", "l":
		return m.handleDrillDown()
	}
	return m, m.table.Update(msg)
}

// handleCloningKey is the clone list: `esc` cancels, then closes. Navigation,

}

// handleNetworksKeyMsg handles keys on the Networks tab
func (m Model) handleNetworksKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openNetworkInspect()
	case "ctrl+n":
		m.resourceForm = NewResourceForm(resourceFormNetwork, m.width-2)
		return m, nil
	case "ctrl+d":
		return m.deleteSelectedNetwork()
	case "p":
		m.pendingAction = "prune-networks"
		m.confirmModal = sharedcomponents.NewConfirmModal("Prune Networks", "Remove all unused networks?")
		return m, nil
	case "ctrl+r":
		m.loadingNets = true
		return m, tea.Batch(m.spinner.Tick, fetchNetworks())
	case "up", "k":
		m.networkTable.Update(msg)
		return m, nil
	case "down", "j":
		m.networkTable.Update(msg)
		return m, nil
	case "g", "home":
		m.networkTable.Update(msg)
		return m, nil
	case "G", "end":
		m.networkTable.Update(msg)
		return m, nil
	}
	return m, nil
}

// handleVolumesKeyMsg handles keys on the Volumes tab
func (m Model) handleVolumesKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "ctrl+n":
		m.resourceForm = NewResourceForm(resourceFormVolume, m.width-2)
		return m, nil
	case "ctrl+d":
		return m.deleteSelectedVolume()
	case "p":
		m.pendingAction = "prune-volumes"
		m.confirmModal = sharedcomponents.NewConfirmModal("Prune Volumes", "Remove all unused volumes?")
		return m, nil
	case "ctrl+r":
		m.loadingVols = true
		return m, tea.Batch(m.spinner.Tick, fetchVolumes())
	case "up", "k":
		m.volumeTable.Update(msg)
		return m, nil
	case "down", "j":
		m.volumeTable.Update(msg)
		return m, nil
	case "g", "home":
		m.volumeTable.Update(msg)
		return m, nil
	case "G", "end":
		m.volumeTable.Update(msg)
		return m, nil
	}
	return m, nil
}

// handleRegistriesKeyMsg handles keys on the Registries tab
func (m Model) handleRegistriesKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "ctrl+n":
		// A member is discovered, not declared, so there is nothing to add here.
		if m.registryGroupSlug != "" {
			return m, nil
		}
		m.registryForm = NewRegistryForm(m.registries, m.width-2)
		return m, nil
	case "e":
		return m.editSelectedRegistry()
	case "l":
		return m.loginSelectedRegistry()
	case "L":
		return m.logoutSelectedRegistry()
	case "ctrl+d":
		return m.deleteSelectedRegistry()
	case "ctrl+r":
		return m.refreshRegistries()
	// Rule 111 offers `l`/`h` as aliases for →/←, but `l` is login on this tab
	// and a key has one role (Rule 135). The arrows are the drill-down.
	case "right":
		return m.enterSelectedGroup()
	case "left", "esc":
		return m.leaveGroup()
	}
	return m, m.registryTable.Update(msg)
}

